-- FOIA dashboard tables (generated by build_tables.py). Run once in the Supabase SQL editor.
-- Everyone can read (the site uses the public anon key); only the loader (database password) can write.

drop table if exists public.statutes_top, public.foia_rows, public.components, public.agencies, public.metrics cascade;

create table public.metrics (
  key  text primary key,      -- key the site uses, e.g. req_recv
  col  text not null unique,  -- column in foia_rows
  kind text not null check (kind in ('sum','avg','max')),
  ord  int  not null
);

create table public.agencies (
  id   int primary key,
  name text not null,
  abbr text
);

create table public.components (
  agency_id int not null references public.agencies(id),
  idx       int not null,
  code      text,
  name      text,
  primary key (agency_id, idx)
);

create table public.foia_rows (
  id        bigint generated always as identity primary key,
  fy        smallint not null,
  agency_id int not null references public.agencies(id),
  comp_idx  int not null,      -- -1 = agency overall row, otherwise components.idx
  req_recv double precision,
  req_proc double precision,
  req_pend double precision,
  d_full double precision,
  d_part double precision,
  d_deny double precision,
  d_norec double precision,
  d_other double precision,
  o3 double precision,
  ex_grant double precision,
  ex_deny double precision,
  ex_med double precision,
  x5_1 double precision,
  x5_2 double precision,
  x5_3 double precision,
  x5_4 double precision,
  x5_5 double precision,
  x5_6 double precision,
  x5_7_a double precision,
  x5_7_b double precision,
  x5_7_c double precision,
  x5_7_d double precision,
  x5_7_e double precision,
  x5_7_f double precision,
  x5_8 double precision,
  x5_9 double precision,
  ap_recv double precision,
  ap_proc double precision,
  ap_pend double precision,
  ad_aff double precision,
  ad_part double precision,
  ad_rev double precision,
  ad_oth double precision,
  x9_1 double precision,
  x9_2 double precision,
  x9_3 double precision,
  x9_4 double precision,
  x9_5 double precision,
  x9_6 double precision,
  x9_7_a double precision,
  x9_7_b double precision,
  x9_7_c double precision,
  x9_7_d double precision,
  x9_7_e double precision,
  x9_7_f double precision,
  x9_8 double precision,
  x9_9 double precision,
  n10_norecords double precision,
  n10_referred double precision,
  n10_withdrawn double precision,
  n10_feerelated double precision,
  n10_notdescribed double precision,
  n10_improperrequest double precision,
  n10_notagency double precision,
  n10_duplicate double precision,
  n10_inlitigation double precision,
  n10_expediteddenial double precision,
  n10_other double precision,
  o11 double precision,
  ar_med double precision,
  ar_avg double precision,
  t14_s double precision,
  t15_s double precision,
  p19_s double precision,
  t14_c double precision,
  t15_c double precision,
  p19_c double precision,
  t14_e double precision,
  t15_e double precision,
  p19_e double precision,
  b16_1_20 double precision,
  b16_21_60 double precision,
  b16_61_100 double precision,
  b16_101_200 double precision,
  b16_201_400 double precision,
  b16_401 double precision,
  b17_1_20 double precision,
  b17_21_60 double precision,
  b17_61_100 double precision,
  b17_101_200 double precision,
  b17_201_400 double precision,
  b17_401 double precision,
  b18_1_20 double precision,
  b18_21_60 double precision,
  b18_61_100 double precision,
  b18_101_200 double precision,
  b18_201_400 double precision,
  b18_401 double precision,
  fw_grant double precision,
  fw_deny double precision,
  fw_med double precision,
  staff double precision,
  staff_ft double precision,
  cost double precision,
  cost_lit double precision,
  fees double precision,
  excl double precision,
  pd_foia double precision,
  pd_prog double precision,
  bl_req double precision,
  bl_app double precision,
  co_recv double precision,
