create index foia_rows_fy_agency on public.foia_rows (fy, agency_id, comp_idx);

create table public.statutes_top (
  fy        smallint not null,
  agency_id int not null references public.agencies(id),
  rank      smallint not null,
  statute   text not null,
  times     int,
  primary key (fy, agency_id, rank)
);

alter table public.metrics enable row level security;
drop policy if exists "public read" on public.metrics;
create policy "public read" on public.metrics for select to anon, authenticated using (true);
grant select on public.metrics to anon, authenticated;
alter table public.agencies enable row level security;
drop policy if exists "public read" on public.agencies;
create policy "public read" on public.agencies for select to anon, authenticated using (true);
grant select on public.agencies to anon, authenticated;
alter table public.components enable row level security;
drop policy if exists "public read" on public.components;
create policy "public read" on public.components for select to anon, authenticated using (true);
grant select on public.components to anon, authenticated;
alter table public.foia_rows enable row level security;
drop policy if exists "public read" on public.foia_rows;
create policy "public read" on public.foia_rows for select to anon, authenticated using (true);
grant select on public.foia_rows to anon, authenticated;
alter table public.statutes_top enable row level security;
drop policy if exists "public read" on public.statutes_top;
create policy "public read" on public.statutes_top for select to anon, authenticated using (true);
grant select on public.statutes_top to anon, authenticated;
